import 'package:family_veda/models/app_notification.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('parses the new NotificationDto fields (type/title/body/linkPath)', () {
    final notification = AppNotification.fromJson({
      'id': 'notif-1',
      'createdAt': '2026-09-28T08:00:00Z',
      'type': 'APPOINTMENT_STATUS_CHANGED',
      'title': 'Appointment confirmed',
      'body': 'Your appointment on 5 Oct was confirmed.',
      'linkPath': '/appointments',
      'readAt': null,
    });

    expect(notification.type, 'APPOINTMENT_STATUS_CHANGED');
    expect(notification.title, 'Appointment confirmed');
    expect(notification.body, 'Your appointment on 5 Oct was confirmed.');
    expect(notification.linkPath, '/appointments');
    expect(notification.isRead, isFalse);
  });

  test('derives isRead from readAt when isRead is absent', () {
    final notification = AppNotification.fromJson({
      'id': 'notif-2',
      'createdAt': '2026-09-28T08:00:00Z',
      'readAt': '2026-09-28T09:00:00Z',
    });
    expect(notification.isRead, isTrue);
  });

  test('still parses legacy case-status notifications unchanged', () {
    final notification = AppNotification.fromJson({
      'id': 'notif-3',
      'createdAt': '2026-09-28T08:00:00Z',
      'isRead': false,
      'caseId': 'case-1',
      'caseStatus': 'APPROVED',
    });
    expect(notification.caseId, 'case-1');
    expect(notification.caseStatus, 'APPROVED');
    expect(notification.title, isNull);
  });
}
